with kept_keys as (select dept_name, id from departments except distinct select dept_name, id from departments where location = 'Bangkok'), verified as (select s.* from departments s inner join kept_keys k on s.dept_name = k.dept_name and s.id = k.id) select dept_name, count(distinct id) as distinct_ids, round(sum(budget) / nullif(count(case when location = 'Chiang Mai' then 1 end), 0), 2) as budget_per_chiang_mai, stddev_samp(budget) as budget_stddev, round(sum(budget) / nullif(count(case when dept_name = 'HR' then 1 end), 0), 2) as budget_per_hr, count(*) as num_rows, count_if(location = 'Bangkok') as bangkok_events from verified group by dept_name having count_if(location = 'Bangkok') > 1 order by budget_per_hr desc;
